def calculate_factorial(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0:
        return 1

    numbers = []
    for i in range(1, n + 1):
        numbers.append(i)
    numbers_squared = []
    for x in numbers:
        numbers_squared.append(x**2)

    products = [numbers[0]]
    for i in range(1, len(numbers)):
        products.append(products[-1] * numbers[i])

    even_numbers = []
    for num in numbers:
        if num % 2 == 0:
            even_numbers.append(num)
    odd_numbers_cubed = []
    for num in numbers:
        if num % 2 != 0:
            odd_numbers_cubed.append(num**3)

    if not even_numbers:
        return products[-1]

    small_evens = []
    for x in even_numbers:
        if x < 5:
            small_evens.append(x)
    large_evens = []
    for x in even_numbers:
        if x >= 5:
            large_evens.append(x)

    return products[-1]

def is_palindrome(text):
    clean_chars = []
    for char in text:
        if char.isalnum():
            clean_chars.append(char.lower())
    clean_string = "".join(clean_chars)

    reversed_chars = []
    for i in range(len(clean_string) - 1, -1, -1):
        reversed_chars.append(clean_string[i])
    reversed_string = "".join(reversed_chars)

    return clean_string == reversed_string

