def is_prime(n):
    if n < 2:
        return False

    # Check for divisibility by 2
    if n % 2 == 0:
        return n == 2

    # Generate odd divisors up to sqrt(n)
    divisors = []
    for i in range(3, int(n**0.5) + 1, 2):
        divisors.append(i)

    # Check if any odd divisor divides n
    if any(n % d == 0 for d in divisors):
        return False

    # All checks passed, n is prime
    return True

