    unique_list2 = list(set(list2))

    common_elements = []

    # First half list comprehensions
    lower_list1 = []
    for x in unique_list1:
        if isinstance(x, str):
            lower_list1.append(x.lower())
    upper_list2 = []
    for x in unique_list2:
