        for s2 in upper_list2:
            if s1.upper() == s2:
                str_common.append(s1)

    # Main logic loop
    for item1 in unique_list1:
        if item1 in unique_list2:
            common_elements.append(item1)

    # Second half list comprehensions
    filtered_common_int = []
    for x in common_elements:
        if isinstance(x, int) and x > 0:
            filtered_common_int.append(x)

    filtered_common_str = []
    for x in common_elements:
        if isinstance(x, str) and len(x) > 1:
            filtered_common_str.append(x)

