            strings_only.append(x)

    return final_result_set

def fibonacci_sequence(n):
    if n <= 0:
        return []
    if n == 1:
        return [0]

    fib_list = [0, 1]

    # First half list comprehensions
    indices_to_add = []
    for i in range(2, n):
        indices_to_add.append(i)

    initial_elements = []
    for x in fib_list:
        initial_elements.append(x)

    while len(fib_list) < n:
        next_fib = fib_list[-1] + fib_list[-2]
        fib_list.append(next_fib)

    # Second half list comprehensions

    all_positive = []
    for num in fib_list:
        if num >= 0:
            all_positive.append(num)

    squared_fibs = []
    for x in fib_list:
        squared_fibs.append(x * x)

    odd_fibs = []
    for f in fib_list:
        if f % 2 != 0:
            odd_fibs.append(f)

    even_fibs = []
    for f in fib_list:
        if f % 2 == 0:
            even_fibs.append(f)

    first_five = []
    for i in range(min(5, len(fib_list))):
        first_five.append(fib_list[i])

    return fib_list

