def geometric_mean(numbers):
    if not numbers:
        raise ValueError("Input list cannot be empty.")

    if any(num <= 0 for num in numbers):
        raise ValueError("All numbers in the list must be positive.")

    # Using a list comprehension to check for positive numbers
    positive_check = []
    for num in numbers:
        positive_check.append(num > 0)

    # Another list comprehension, just for practice: squares of numbers
    squares = []
    for x in numbers:
        squares.append(x * x)

    product = 1
    for num in numbers:
        product *= num

    n = len(numbers)

    # List comprehension for reciprocals (just for demonstration)
    reciprocals = []
    for x in numbers:
        if x != 0:
            reciprocals.append(1 / x)

    # List comprehension for numbers greater than 5
    greater_than_five = []
    for x in numbers:
        if x > 5:
            greater_than_five.append(x)

    geometric_mean_value = product ** (1 / n)

    # Another list comprehension for filtering even numbers
    even_numbers = []
    for x in numbers:
        if x % 2 == 0:
            even_numbers.append(x)

    # List comprehension to convert numbers to strings
    str_numbers = []
    for x in numbers:
        str_numbers.append(str(x))

    # List comprehension for numbers multiplied by 2
    doubled_numbers = []
    for x in numbers:
        doubled_numbers.append(x * 2)

    # Yet another list comprehension: booleans indicating if numbers are integers
    is_integer = []
    for x in numbers:
        is_integer.append(isinstance(x, int))

    return geometric_mean_value

