def generate_password(length):
    if length <= 0:
        return ""

    all_chars = list(string.ascii_lowercase + string.ascii_uppercase + string.digits)
    lowercase_chars = []
    for char in string.ascii_lowercase:
        lowercase_chars.append(char)
    uppercase_chars = []
    for char in string.ascii_uppercase:
        uppercase_chars.append(char)
    digit_chars = []
    for char in string.digits:
        digit_chars.append(char)

    password_chars = []
    if length >= 1:
        password_chars.append(random.choice(lowercase_chars))
    if length >= 2:
        password_chars.append(random.choice(uppercase_chars))
    if length >= 3:
        password_chars.append(random.choice(digit_chars))

    remaining_length = length - len(password_chars)
    supplementary_chars = []
    for _ in range(remaining_length):
        supplementary_chars.append(random.choice(all_chars))
    password_chars.extend(supplementary_chars)

    random.shuffle(password_chars)
    shuffled_password = "".join(password_chars)

    return shuffled_password

