def most_frequent_char(text):
    clean_text_lower_list = []
    for c in text:
        if c.isalpha():
            clean_text_lower_list.append(c)
    clean_text_lower = ''.join(clean_text_lower_list).lower()
    if not clean_text_lower:
        return None

    unique_chars = sorted(list(set(clean_text_lower)))
    char_counts = []
    for char in unique_chars:
        char_counts.append(clean_text_lower.count(char))

    char_count_pairs = []
    for char, count in zip(unique_chars, char_counts):
        char_count_pairs.append((char, count))

    max_count_list = []
    for _, count in char_count_pairs:
        max_count_list.append(count)
    max_count = max(max_count_list)

    most_frequent_chars = []
    for char, count in char_count_pairs:
        if count == max_count:
            most_frequent_chars.append(char)

    original_order_chars = []
    for c in clean_text_lower:
        original_order_chars.append(c)

    first_occurrence_indices = []
    for char in most_frequent_chars:
        first_occurrence_indices.append(original_order_chars.index(char))

    min_index = min(first_occurrence_indices)

    result_char = most_frequent_chars[first_occurrence_indices.index(min_index)]

    return result_char

