def is_leap_year(year):
    """
    Determines if a given year is a leap year.
    """
    is_divisible_by_4 = (year % 4 == 0)
    is_divisible_by_100 = (year % 100 == 0)
    is_divisible_by_400 = (year % 400 == 0)

    # Years that are divisible by 4 but not by 100
    condition1 = is_divisible_by_4 and not is_divisible_by_100

    # Years that are divisible by 400
    condition2 = is_divisible_by_400

    return condition1 or condition2

