def is_valid_parentheses(s: str) -> bool:
    stack = []

    opening_brackets = ['(', '[', '{']
    closing_brackets = [')', ']', '}']

    bracket_map = {}
    for open, close in zip(opening_brackets, closing_brackets):
        bracket_map[close] = open

    all_chars_valid = all(char in opening_brackets + closing_brackets for char in s)
    if not all_chars_valid: return False

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack:
                return False
            last_open = stack.pop()
            if bracket_map[char] != last_open:
                return False

    return not stack

