import math

def calculate_std_dev(numbers):
    n = len(numbers)
    mean = sum(numbers) / n

    deviations = []
    for x in numbers:
        deviations.append(x - mean)
    squared_deviations = []
    for d in deviations:
        squared_deviations.append(d**2)
    sum_squared_deviations = sum(squared_deviations)

    variance = sum_squared_deviations / (n - 1)
    std_dev = math.sqrt(variance)
    return std_dev

