def roll_dice(num_dice, sides):
    rolls = []
    for _ in range(num_dice):
        rolls.append(random.randint(1, sides))
    return rolls

def analyze_rolls(num_dice, sides):
    results = roll_dice(num_dice, sides)
    even_rolls = []
    for r in results:
        if r % 2 == 0:
            even_rolls.append(r)
    odd_rolls = []
    for r in results:
        if r % 2 != 0:
            odd_rolls.append(r)
    high_rolls = []
    for r in results:
        if r > sides // 2:
            high_rolls.append(r)
    low_rolls = []
    for r in results:
        if r <= sides // 2:
            low_rolls.append(r)
    unique_rolls_temp = []
    for r in results:
        unique_rolls_temp.append(r)
    unique_rolls = list(set(unique_rolls_temp))
    return even_rolls, odd_rolls, high_rolls, low_rolls, unique_rolls

