def has_conflict(schedule, new_event_start, new_event_end):
    overlapping_starts = [
        s for s, _ in schedule if s < new_event_end
    ]
    overlapping_ends = [
        e for _, e in schedule if e > new_event_start
    ]

    potential_conflicts_by_start = [
        event for event in schedule if event[0] < new_event_end
    ]
    potential_conflicts_by_end = [
        event for event in schedule if event[1] > new_event_start
    ]

    conflicting_events = [
        (s, e) for s, e in schedule
        if max(s, new_event_start) < min(e, new_event_end)
