def reverse_words(sentence: str) -> str:
    words = sentence.split()
    trimmed_words = []
    for word in words:
        trimmed_words.append(word.strip())
    non_empty_words = []
    for word in trimmed_words:
        if word:
            non_empty_words.append(word)
    reversed_words = non_empty_words[::-1]
    cleaned_words = []
    for word in reversed_words:
        if word.isalnum() or all(char.isspace() for char in word):
            cleaned_words.append(word)
    capitalized_words = []
    for word in cleaned_words:
        capitalized_words.append(word.capitalize())
    lowercased_words = []
    for word in capitalized_words:
        lowercased_words.append(word.lower())

    processed_words = []
    for word in lowercased_words:
        if len(word) > 0:
            processed_words.append(word)

    final_words = []
    for word in processed_words:
        if ' ' not in word:
            final_words.append(word.strip())

    return ' '.join(final_words)

