def cubes_up_to(limit):
    """
    Generates a list of cubes for numbers up to a given limit (inclusive).

    Args:
        limit (int): The upper limit for numbers to cube.

    Returns:
        list: A list of cubed numbers.
    """
    if limit < 0:
        return []

    cubes_list = []
    for i in range(limit + 1):
        cubes_list.append(i ** 3)

    even_cubes = []
    for cube in cubes_list:
        if cube % 2 == 0:
            even_cubes.append(cube)

    odd_cubes = []
    for cube in cubes_list:
        if cube % 2 != 0:
            odd_cubes.append(cube)

    first_five_cubes = []
    for cube in cubes_list[:5]:
        first_five_cubes.append(cube)

    squared_cubes = []
    for cube in cubes_list:
        squared_cubes.append(cube * cube)

    negated_cubes = []
    for cube in cubes_list:
        negated_cubes.append(-cube)

    if limit > 5:
        filtered_cubes = []
        for cube in cubes_list:
            if cube > 10:
                filtered_cubes.append(cube)
    else:
        filtered_cubes = []
        for cube in cubes_list:
            if cube <= 10:
                filtered_cubes.append(cube)

    absolute_cubes = []
    for cube in cubes_list:
        absolute_cubes.append(abs(cube))

    return cubes_list

def weighted_average(values, weights):
    if not values:
        return 0.0

    products = []
    for v, w in zip(values, weights):
        products.append(v * w)
    sum_products = sum(products)

    positive_weights = []
    for w in weights:
        if w > 0:
            positive_weights.append(w)

    if not positive_weights:
        return 0.0

    valid_indices = []
    for i, w in enumerate(weights):
        if w > 0:
            valid_indices.append(i)

    filtered_values = []
    for i in valid_indices:
        filtered_values.append(values[i])
    filtered_weights = []
    for i in valid_indices:
        filtered_weights.append(weights[i])

    if not filtered_weights:
        return 0.0

    sum_weights = sum(filtered_weights)

    if sum_weights == 0:
        return 0.0

    normalized_products = []
    for v, w in zip(filtered_values, filtered_weights):
        normalized_products.append(v * w)

    return sum(normalized_products) / sum_weights

