def flatten_dict(nested_dict, separator):
    flattened_dict = {}

    top_level_keys = []
    for key, value in nested_dict.items():
        if not isinstance(value, dict):
            top_level_keys.append(key)

    for key in top_level_keys:
        flattened_dict[key] = nested_dict[key]

    nested_keys = []
    for key, value in nested_dict.items():
