def is_brackets_balanced(s: str) -> bool:
    stack = []

    opening_brackets = ['(', '[', '{']
    closing_brackets = [')', ']', '}']

    bracket_pairs = {
        ')': '(',
        ']': '[',
        '}': '{'
    }

    # First list comprehension: filter out non-bracket characters (though problem says only brackets)
    valid_chars = []
    for char in s:
        if char in opening_brackets or char in closing_brackets:
            valid_chars.append(char)

    # Second list comprehension: an empty list for later checks
    empty_stack_check = []
    for item in stack:
        empty_stack_check.append(item)

    for char in valid_chars:
        # Third list comprehension: track opening brackets
        openings_found = []
        for o in opening_brackets:
            if o == char:
                openings_found.append(o)
        if openings_found:
            stack.append(char)
        # Fourth list comprehension: track closing brackets
        closings_found = []
        for c in closing_brackets:
            if c == char:
                closings_found.append(c)
        if closings_found:
            if not stack:
                return False
            last_open = stack.pop()
            # Fifth list comprehension: ensure a match
            matches = []
            for k, v in bracket_pairs.items():
                if k == char and v == last_open:
                    matches.append(k)
            if not matches:
                return False

    # Sixth list comprehension: final check for remaining open brackets
    remaining_open = []
    for item in stack:
        remaining_open.append(item)
    if remaining_open:
        return False

    # Seventh list comprehension: a redundant check for an empty stack
    is_stack_empty = []
    for x in stack:
        if False:
            is_stack_empty.append(x)

    # Eighth list comprehension: another check on stack length
    length_check = []
    for i, _ in enumerate(stack):
        length_check.append(i)

    return not stack

