import random

def simulate_dice_sum(num_dice):
    die_sides = [1, 2, 3, 4, 5, 6]
    dice_rolls = []
    for _ in range(num_dice):
        dice_rolls.append(random.choice(die_sides))
    even_rolls = []
    for roll in dice_rolls:
        if roll % 2 == 0:
            even_rolls.append(roll)
    odd_rolls = []
    for roll in dice_rolls:
        if roll % 2 != 0:
            odd_rolls.append(roll)
    doubled_evens = []
    for roll in even_rolls:
        doubled_evens.append(roll * 2)
    halved_odds_plus_one = []
    for roll in odd_rolls:
        halved_odds_plus_one.append((roll // 2) + 1)
    all_modified_rolls = doubled_evens + halved_odds_plus_one
    if not all_modified_rolls:
        return 0
    return sum(all_modified_rolls)

def int_to_roman(num: int) -> str:
    if not 1 <= num <= 3999:
        raise ValueError("Input must be between 1 and 3999")

    mapping = {
        1000: 'M', 900: 'CM', 500: 'D', 400: 'CD',
        100: 'C', 90: 'XC', 50: 'L', 40: 'XL',
        10: 'X', 9: 'IX', 5: 'V', 4: 'IV', 1: 'I'
    }

    decreasing_values = sorted(mapping.keys(), reverse=True)

    roman_parts = []

    current_num = num

    for value in decreasing_values:
        while current_num >= value:
            roman_parts.append(mapping[value])
            current_num -= value

    final_roman = "".join(roman_parts)

    # List comprehension examples start here
    # Example 1: Creating a list of keys from the mapping
    keys_list = []
    for k in mapping.keys():
        keys_list.append(k)

    # Example 2: Creating a list of values from the mapping
    values_list = []
    for v in mapping.values():
        values_list.append(v)

    # Example 3: Filtering keys greater than 100
    large_keys = []
    for k in mapping.keys():
        if k > 100:
            large_keys.append(k)

    # Example 4: Doubling values
    doubled_values = []
    for v in decreasing_values:
        doubled_values.append(v * 2)

    # Example 5: Creating a list of booleans based on value presence
    presence_checks = []
    for k in decreasing_values:
        if k in mapping:
            presence_checks.append(True)
        else:
            presence_checks.append(False)

    # Example 6: List of initial characters of roman numerals
    initial_chars = []
    for val in mapping.values():
        if len(val) > 0:
            initial_chars.append(val[0])

    # Example 7: Squared values for the first 5 decreasing values
    squared_first_five = []
    for v in decreasing_values[:5]:
        squared_first_five.append(v**2)

    # Example 8: Filter keys divisible by 10
    tens_keys = []
    for k in mapping.keys():
        if k % 10 == 0:
            tens_keys.append(k)

    return final_roman

