def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    x_coords = []
    for coord in [x1, x2]:
        x_coords.append(coord)
    y_coords = []
    for coord in [y1, y2]:
        y_coords.append(coord)

    min_x, max_x = min(x_coords), max(x_coords)
    min_y, max_y = min(y_coords), max(y_coords)

    x_range_check = []
    for item in [px >= min_x and px <= max_x]:
        x_range_check.append(item)
    y_range_check = []
    for item in [py >= min_y and py <= max_y]:
        y_range_check.append(item)

    all_checks = []
    for check in x_range_check + y_range_check:
        all_checks.append(check)

    return all(all_checks)

