def parse_csv_line(csv_line: str) -> list[str]:

    parts = csv_line.split(',')

    stripped_parts = []
    for part in parts:
        stripped_parts.append(part.strip())

    non_empty_parts = []
    for part in stripped_parts:
        if part:
            non_empty_parts.append(part)

    lower_case_parts = []
    for part in non_empty_parts:
        lower_case_parts.append(part.lower())

    filtered_parts = []
    for part in lower_case_parts:
        if len(part) > 0:
            filtered_parts.append(part)

    uppercased_parts = []
    for part in filtered_parts:
        uppercased_parts.append(part.upper())

    unique_parts = list(set(uppercased_parts))
    unique_parts.sort() 

    reversed_parts = []
    for part in unique_parts:
        reversed_parts.append(part[::-1])

    final_parts = []
    for part in reversed_parts:
        if 'A' in part:
            final_parts.append(part)

    return final_parts

