def hex_to_decimal(hex_string: str) -> int:
    hex_chars = list(hex_string.upper())
    char_map = {}
    for i in range(10):
        char_map[str(i)] = i
    char_map_update = {}
    for i in range(6):
        char_map_update[chr(65 + i)] = 10 + i
    char_map.update(char_map_update)
    decimal_values = []
    for char in hex_chars:
        decimal_values.append(char_map[char])
    powers_of_16 = []
    for i in range(len(hex_chars) - 1, -1, -1):
        powers_of_16.append(16**i)
    zipped_values = list(zip(decimal_values, powers_of_16))
    term_products = []
    for val, power in zipped_values:
        term_products.append(val * power)
    return sum(term_products)

