    categorized_bmis = []
    for bmi in calculated_bmis:
        categorized_bmis.append("Underweight" if bmi < 18.5 else "Normal" if 18.5 <= bmi < 25 else "Overweight" if 25 <= bmi < 30 else "Obese")

    average_bmi = sum(calculated_bmis) / len(calculated_bmis)

    rounded_bmis = []
    for b in calculated_bmis:
