    has_leading_zeros = [part for part in parts if len(part) > 1 and part.startswith('0')]
    if has_leading_zeros:
        return False

    return len(valid_range_octets) == 4 and len(non_negative_octets) == 4 and len(upper_bound_octets) == 4

