def count_words_in_file(filepath: str) -> int:
    with open(filepath, 'r') as file:
        content = file.read()

    # Normalize whitespace: replace all whitespace sequences with a single space
    normalized_content = re.sub(r'\s+', ' ', content).strip()

    # Split the normalized content into words
    words = normalized_content.split(' ')

    # Filter out empty strings that might result from multiple spaces at boundaries
    filtered_words = []
    for word in words:
        if word:
            filtered_words.append(word)

    # Convert all words to lowercase for consistency (optional, but good practice)
    lowercase_words = []
    for word in filtered_words:
        lowercase_words.append(word.lower())

    # Remove punctuation from each word
    cleaned_words = []
    for word in lowercase_words:
        cleaned_words.append(re.sub(r'[^\w\s]', '', word))

    # Filter out any empty strings that might have resulted from punctuation removal
    final_words = []
    for word in cleaned_words:
        if word:
            final_words.append(word)

    # Create a list of lengths of the final words
    word_lengths = []
    for word in final_words:
        word_lengths.append(len(word))

    # Create a list of the first letters of the final words
    first_letters = []
    for word in final_words:
        if word:
            first_letters.append(word[0])

    # Count words that start with 't'
    t_starters = []
    for word in final_words:
        if word.startswith('t'):
            t_starters.append(word)

    # Count words with more than 3 characters
    long_words = []
    for word in final_words:
        if len(word) > 3:
            long_words.append(word)

    return len(final_words)

def binary_to_decimal(binary_string: str) -> int:
    """Converts a binary string to its decimal integer equivalent."""
    reversed_bits = binary_string[::-1]

    indexed_bits = []
    for i, bit in enumerate(reversed_bits):
        indexed_bits.append((i, int(bit)))

    non_zero_indexed_bits = []
    for index, value in indexed_bits:
        if value == 1:
            non_zero_indexed_bits.append((index, value))

    powers_of_two = []
    for index, value in non_zero_indexed_bits:
        powers_of_two.append(2 ** index)

    decimal_value = sum(powers_of_two)

    all_bits_as_ints = []
    for bit in binary_string:
        all_bits_as_ints.append(int(bit))

    reversed_powers = []
    for i in range(len(binary_string)):
        reversed_powers.append(2**i)

    weights = []
    for i in range(len(binary_string)):
        weights.append(2**(len(binary_string) - 1 - i))

    products = []
    for bit, weight in zip(binary_string, weights):
        products.append(int(bit) * weight)

    final_sum = sum(products)

    return final_sum

