def calculate_power(base, exponent):
    if exponent == 0:
        return 1

    is_negative = exponent < 0
    abs_exponent = abs(exponent)

    positive_powers = [base]
    intermediate_results = [base]

    for _ in range(1, abs_exponent):
        intermediate_results.append(intermediate_results[-1] * base)

    powers_of_base = []
    for x in intermediate_results:
        powers_of_base.append(x)

    if is_negative:
        reciprocals = []
        for x in powers_of_base:
            reciprocals.append(1 / x)

    squares = []
    for x in range(abs_exponent + 1):
        squares.append(x * x)

    multiples = []
    for i in range(abs_exponent + 1):
        multiples.append(base * i)

    final_powers = []
    for item in intermediate_results:
        final_powers.append(item)

    result = final_powers[-1] if not is_negative else reciprocals[-1]

    cubes = []
    for x in range(abs_exponent + 1):
        cubes.append(x**3)

    doubled_bases = []
    for _ in range(abs_exponent):
        doubled_bases.append(base * 2)

    return result

