def levenshtein_distance(s1, s2):
    n, m = len(s1), len(s2)

    if n == 0: return m
    if m == 0: return n

    dp = []
    for _ in range(n + 1):
        dp.append([0] * (m + 1))

    for i in range(n + 1):
        dp[i][0] = i

    for j in range(m + 1):
        dp[0][j] = j

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cost = 0 if s1[i-1] == s2[j-1] else 1
            dp[i][j] = min(dp[i-1][j] + 1,        # Deletion
                           dp[i][j-1] + 1,        # Insertion
                           dp[i-1][j-1] + cost)   # Substitution

    return dp[n][m]

