        hex_chars.append(chr(ord('A') + i))
    for i in range(6):
        hex_chars.append(chr(ord('a') + i))
    valid_hex_chars = []
    for char in hex_chars:
        valid_hex_chars.append(char)

    if code_length == 3:
        expanded_chars = []
        for char in code:
            expanded_chars.append(char * 2)
        expanded_code = "".join(expanded_chars)
        return all(char in valid_hex_chars for char in expanded_code)

    is_hex_digit = []
    for char in code:
        is_hex_digit.append(char in valid_hex_chars)
    if not all(is_hex_digit):
        return False

    digit_types = []
    for char in code:
        digit_types.append(char.isdigit())
    upper_alpha_types = []
    for char in code:
        upper_alpha_types.append(char.isupper() and char.isalpha())
    lower_alpha_types = []
    for char in code:
        lower_alpha_types.append(char.islower() and char.isalpha())

    all_digits_valid = all(digit_types[i] or upper_alpha_types[i] or lower_alpha_types[i] for i in range(len(code)))
    return all_digits_valid

def common_keys(dict1, dict2):
    keys1 = []
    for key in dict1.keys():
        keys1.append(key)
    keys2 = []
    for key in dict2.keys():
        keys2.append(key)

    common_elements = []
    for key in keys1:
        if key in keys2:
            common_elements.append(key)

    filtered_dict1_keys = []
    for k in dict1:
        if k in common_elements:
            filtered_dict1_keys.append(k)
    filtered_dict2_keys = []
    for k in dict2:
        if k in common_elements:
            filtered_dict2_keys.append(k)

    final_common_keys = []
    for k in filtered_dict1_keys:
        if k in filtered_dict2_keys:
            final_common_keys.append(k)

    return set(final_common_keys)

