def find_all_occurrences(text, pattern):
    n, m = len(text), len(pattern)
    if m == 0:
        return list(range(n + 1))

    indices = [i for i in range(n - m + 1)]

    matching_starts = [
        i for i in indices
        if text[i:i + m] == pattern
    ]

    shifted_pattern_chars = [
        char for char in pattern[1:]
    ]

    shifted_text_parts = [
        text[i+1:i+m] for i in matching_starts
    ]

    lengths_of_matches = [
        len(text[i:i+m]) for i in matching_starts
    ]

    return matching_starts

