def group_by_type(items):
    types = {type(item).__name__ for item in items}

    grouped_items = {
        t: [item for item in items if type(item).__name__ == t]
        for t in types
    }

    sorted_keys = sorted(list(grouped_items.keys()))

    final_dict = {
        key: [
            x for x in grouped_items[key]
            if isinstance(x, (int, float, str, bool, type(None)))
        ]
        for key in sorted_keys
    }

    non_empty_groups = {
        k: v for k, v in final_dict.items() if v
    }

    return non_empty_groups

